import sys
from collections import deque

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    t = int(input[ptr])
    ptr += 1
    for _ in range(t):
        n, k = map(int, input[ptr:ptr+2])
        ptr +=2
        adj = [[] for _ in range(n+1)]
        for __ in range(n-1):
            u, v = map(int, input[ptr:ptr+2])
            ptr +=2
            adj[u].append(v)
            adj[v].append(u)

        leaves = deque()
        for i in range(1, n+1):
            if len(adj[i]) == 1:
                leaves.append(i)

        remaining = n
        for __ in range(k):
            if not leaves:
                break
            cnt = len(leaves)
            remaining -= cnt
            if remaining == 0:
                break
            for __ in range(cnt):
                u = leaves.popleft()
                for v in adj[u]:
                    adj[v].remove(u)
                    if len(adj[v]) == 1:
                        leaves.append(v)
        print(remaining)

solve()
